Config load(const std::filesystem::path& p) {
    if (p.empty())
        throw std::invalid_argument{"empty path"};       // guard: bad input
    std::ifstream in{p};
    if (!in)
        return Config::defaults();                        // guard: recoverable miss
    Config cfg = parse(in);                               // happy path stays flat
    assert(cfg.is_consistent());                          // invariant, debug only
    return cfg;
}
